"const fs = require('fs');

const matchesPath = 'c:/Users/Sajad/Desktop/SaSLoop/scratch/matches.txt';
if (!fs.existsSync(matchesPath)) {
  console.log("matches.txt does not exist");
  process.exit(1);
}

const content = fs.readFileSync(matchesPath, 'utf8');
console.log("matches.txt total length:", content.length);

// Let's find "dial-spin-sequence" in matches.txt
let idx = 0;
let occurrences = [];
while (true) {
  idx = content.indexOf('dial-spin-sequence', idx);
  if (idx === -1) break;
  occurrences.push(idx);
  idx += 'dial-spin-sequence'.length;
}

console.log("Number of occurrences of dial-spin-sequence in matches.txt:", occurrences.length);

occurrences.forEach((pos, index) => {
  console.log(`Occurrence ${index + 1} at position ${pos}`);
  // Let's look backward for "const TransitionSplashScreen" and forward for the end of the component
  let startIdx = content.lastIndexOf('const TransitionSplashScreen =', pos);
  let endIdx = content.indexOf('export default', pos);
  if (endIdx === -1) endIdx = content.indexOf('const SidebarIcon', pos);
  if (endIdx === -1) endIdx = pos + 5000; // fallback

  console.log(`Guessed start: ${startIdx}, end: ${endIdx}`);
  if (startIdx !== -1) {
    const chunk = content.slice(startIdx, endIdx);
    console.log(`Chunk length: ${chunk.length}`);
    // Check if it contains '<truncated'
    console.log("Chunk contains '<truncated'?", chunk.includes('<truncated'));

    // Write out the chunk
    fs.writeFileSync(`c:/Users/Sajad/Desktop/SaSLoop/scratch/recovered_chunk_${index + 1}.txt`, chunk, 'utf8');
  }
});
"
